<script lang="ts">
 import { onMount } from 'svelte';
 import { request } from './api';
 import { AlertBanner, PageHeader, RefreshButton } from './ui';
 type Kind='text'|'textarea'|'number'|'date'|'select'|'file';
 type Field={key:string;label:string;kind:Kind;required:boolean;options:string[]};
 type Template={id:string;title:string;category:string;description:string;fields:Field[];submission_count?:number;is_active:boolean};
 type Submission={id:string;title:string;employee?:string;status:string;payload:Record<string,string>;created_at:string};
 const blank=():Field=>({key:`field_${Date.now()}`,label:'',kind:'text',required:false,options:[]});
 let templates=$state<Template[]>([]),submissions=$state<Submission[]>([]),title=$state(''),category=$state('general'),description=$state(''),editorFields=$state<Field[]>([blank()]),editing=$state<string|null>(null),reviewNote=$state(''),reviewing=$state(''),error=$state(''),notice=$state(''),loading=$state(true),saving=$state(false);
 function reset(){title='';category='general';description='';editorFields=[blank()];editing=null;}
 function validFields(){return editorFields.map((field,index)=>({...field,key:field.key.trim()||field.label.toLowerCase().replace(/[^a-z0-9]+/g,'_')||`field_${index+1}`,label:field.label.trim(),options:field.options.filter(Boolean)})).filter(field=>field.label);}
 async function load(){loading=true;error='';try{const data=await request<{templates:Template[];submissions:Submission[]}>('/v1/admin/custom-forms');templates=data.templates;submissions=data.submissions;}catch(cause){error=cause instanceof Error?cause.message:'Tidak dapat memuat formulir.';}finally{loading=false;}}
 async function save(){const fields=validFields();if(!title.trim()||!category.trim()||!fields.length){error='Isi nama, kategori, dan minimal satu field terlebih dahulu.';return;}saving=true;error='';try{const path=editing?`/v1/admin/custom-forms/${editing}`:'/v1/admin/custom-forms';await request(path,{method:'POST',body:JSON.stringify({title,category,description,fields})});notice=editing?'Versi template diperbarui.':'Template baru dibuat.';reset();await load();}catch(cause){error=cause instanceof Error?cause.message:'Template tidak dapat disimpan.';}finally{saving=false;}}
 function edit(template:Template){editing=template.id;title=template.title;category=template.category;description=template.description;editorFields=template.fields.map(field=>({...field,options:[...field.options]}));notice='';window.scrollTo({top:0,behavior:'smooth'});}
 async function review(id:string){saving=true;error='';try{await request(`/v1/admin/custom-forms/submissions/${id}/review`,{method:'POST',body:JSON.stringify({note:reviewNote})});notice='Submission telah ditinjau.';reviewing='';reviewNote='';await load();}catch(cause){error=cause instanceof Error?cause.message:'Review tidak dapat disimpan.';}finally{saving=false;}}
 async function templateState(id:string,is_active:boolean){saving=true;error='';try{await request(`/v1/admin/custom-forms/${id}/state`,{method:'POST',body:JSON.stringify({is_active})});notice=is_active?'Template diaktifkan.':'Template dinonaktifkan.';await load();}catch(cause){error=cause instanceof Error?cause.message:'Status template tidak dapat diubah.';}finally{saving=false;}}
 onMount(load);
</script>

<main class="workspace-page">
 <PageHeader title="Custom forms" description="Rancang template, tinjau respons, dan arahkan pekerjaan follow-up." backHref="/admin/dashboard" />
 {#if error}<AlertBanner variant="error">{error}</AlertBanner>{/if}{#if notice}<AlertBanner variant="success">{notice}</AlertBanner>{/if}
 <section class="panel"><header><div><h2>{editing?'Edit template':'Template baru'}</h2><p>Perubahan field membuat versi schema baru; respons lama tetap tersimpan.</p></div>{#if editing}<button class="quiet" onclick={reset}>Batal edit</button>{/if}</header>
  <form novalidate onsubmit={(event)=>{event.preventDefault();void save();}}>
   <div class="grid"><label>Nama template<input bind:value={title} placeholder="Contoh: Form kunjungan lokasi" required /></label><label>Kategori<input bind:value={category} placeholder="Contoh: Operasional" required /></label></div><label>Deskripsi<textarea bind:value={description} placeholder="Kapan dan oleh siapa formulir ini digunakan?"></textarea></label>
   <fieldset><legend>Field formulir</legend><p class="hint">Pilih jenis field dan tandai wajib jika respons harus diisi. Field unggahan menyimpan berkas privat milik pengirim.</p>{#each editorFields as field,index (field.key)}<div class="field-row"><label>Label<input bind:value={field.label} placeholder="Contoh: Lokasi" /></label><label>Jenis<select bind:value={field.kind}><option value="text">Teks singkat</option><option value="textarea">Teks panjang</option><option value="number">Angka</option><option value="date">Tanggal</option><option value="select">Pilihan</option><option value="file">Unggah berkas</option></select></label>{#if field.kind==='select'}<label>Pilihan<input value={field.options.join(', ')} oninput={(event)=>field.options=event.currentTarget.value.split(',').map(value=>value.trim()).filter(Boolean)} placeholder="Audit, Instalasi" /></label>{/if}<label class="check"><input type="checkbox" bind:checked={field.required} /> Wajib diisi</label><button type="button" class="icon-button" aria-label="Hapus field" disabled={editorFields.length===1} onclick={()=>editorFields=editorFields.filter((_,item)=>item!==index)}>×</button></div>{/each}<button type="button" class="quiet" onclick={()=>editorFields=[...editorFields,blank()]}>+ Tambah field</button></fieldset><footer><button disabled={saving}>{saving?'Menyimpan…':editing?'Simpan versi baru':'Buat template'}</button></footer>
  </form>
 </section>
 <section class="panel"><header><div><h2>Template</h2><p>{templates.length} template tersedia untuk tim.</p></div><RefreshButton onclick={load} label="Muat ulang" /></header>{#if loading}<p class="muted">Memuat template…</p>{:else}{#each templates as template (template.id)}<article class="template"><div><strong>{template.title}</strong><small>{template.category} · {template.fields.length} field · {template.submission_count ?? 0} respons · {template.is_active?'Aktif':'Nonaktif'}</small><p>{template.description||'Tanpa deskripsi.'}</p></div><div class="actions"><button class="quiet" onclick={()=>edit(template)}>Edit</button><button class="quiet" disabled={saving} onclick={()=>templateState(template.id,!template.is_active)}>{template.is_active?'Nonaktifkan':'Aktifkan'}</button></div></article>{:else}<p class="muted">Belum ada template.</p>{/each}{/if}</section>
 <section class="panel"><h2>Submission terbaru</h2>{#each submissions as submission (submission.id)}<article class="submission"><div><strong>{submission.title}</strong><small>{submission.employee ?? 'Karyawan'} · {submission.status} · {new Date(submission.created_at).toLocaleString('id-ID')}</small><p>{Object.entries(submission.payload).map(([key,value])=>`${key}: ${value}`).join(' · ')}</p></div>{#if submission.status==='submitted'}<div class="actions">{#if reviewing===submission.id}<form novalidate onsubmit={(event)=>{event.preventDefault();void review(submission.id);}}><label>Catatan review<input bind:value={reviewNote} placeholder="Catatan untuk pengirim" /></label><button disabled={saving}>Simpan review</button></form>{:else}<button class="quiet" onclick={()=>reviewing=submission.id}>Review</button>{/if}</div>{/if}</article>{:else}<p class="muted">Belum ada submission.</p>{/each}</section>
</main>

<style>
 .workspace-page{display:grid;gap:var(--space-4)} .panel{display:grid;gap:var(--space-3);padding:var(--space-4);border-radius:var(--radius)} header,.template,.submission,.field-row,.actions,footer{display:flex;gap:var(--space-3);justify-content:space-between;align-items:start} h2{margin:0} p,small,.hint{display:block;margin:0;color:var(--muted);font-size:var(--text-sm)} form,fieldset{display:grid;gap:var(--space-3)} fieldset{border:1px solid var(--line);border-radius:var(--radius-sm);padding:var(--space-3)} legend{font-weight:700} label{display:grid;gap:6px;font-weight:600;font-size:var(--text-sm)} .grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--space-3)} .field-row{align-items:end;border-top:1px solid var(--line);padding-top:var(--space-3)} .field-row label{flex:1}.check{display:flex;align-items:center;min-height:42px;white-space:nowrap}.icon-button{width:40px;padding:0;font-size:24px}.quiet{background:var(--surface-alt);border:1px solid var(--line);color:var(--text)} .actions{flex-wrap:wrap}.template,.submission{border-top:1px solid var(--line);padding-top:var(--space-3)}@media(max-width:760px){.grid{grid-template-columns:1fr}.field-row,.template,.submission,header{flex-direction:column;align-items:stretch}.icon-button{width:100%}}
</style>
